window.astraDistrictArtwork=["","",""];
/* R75 generated geological materials. Normal/roughness maps are derived once
 * during loading and mounted with the albedo maps, before the engine starts. */
window.astraDistrictReady=(async()=>{
 const maps=new Map();
 async function png(canvas){return new Uint8Array(await (await new Promise(r=>canvas.toBlob(r,'image/png'))).arrayBuffer());}
 for(let i=0;i<astraDistrictArtwork.length;i++){
  const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject;image.src='data:image/jpeg;base64,'+astraDistrictArtwork[i];});
  const color=document.createElement('canvas');color.width=color.height=1024;const ctx=color.getContext('2d');ctx.drawImage(image,0,0,1024,1024);
  maps.set('g'+(16+i)+'.png',await png(color));
  const normal=document.createElement('canvas');normal.width=normal.height=512;const dc=normal.getContext('2d',{willReadFrequently:true});dc.drawImage(image,0,0,512,512);
  const source=dc.getImageData(0,0,512,512),out=dc.createImageData(512,512),height=new Float32Array(512*512);
  for(let p=0;p<height.length;p++)height[p]=(source.data[p*4]*.22+source.data[p*4+1]*.70+source.data[p*4+2]*.08)/255;
  for(let y=0;y<512;y++)for(let x=0;x<512;x++){
   const p=y*512+x,dx=(height[y*512+((x+1)&511)]-height[y*512+((x+511)&511)])*2.4,dy=(height[((y+1)&511)*512+x]-height[((y+511)&511)*512+x])*2.4;
   const scale=1/Math.sqrt(1+dx*dx+dy*dy);out.data[p*4]=128-dx*scale*127;out.data[p*4+1]=128-dy*scale*127;out.data[p*4+2]=205+height[p]*32;out.data[p*4+3]=75+height[p]*105;
  }
  dc.putImageData(out,0,0);maps.set('g'+(16+i)+'-n.png',await png(normal));color.width=normal.width=1;
 }
 window.astraDistrictArtwork=null;return maps;
})();
